package dev.cazajefes;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
import org.bukkit.Material;
public class RareCollectionTest {
 @Test public void upgradingToEightRequiresTwoValidSamePowerBooksAndNoOverflow(){assertEquals(8,RareDefinitions.upgradedLevel("invisibility",List.of(7,1)));assertEquals(0,RareDefinitions.upgradedLevel("invisibility",List.of(8,1)));assertEquals(0,RareDefinitions.upgradedLevel("invisibility",List.of(0,1)));assertEquals(0,RareDefinitions.upgradedLevel("invisibility",List.of(7)));assertEquals(0,RareDefinitions.upgradedLevel("hardy",List.of(1,1)));assertTrue(RareDefinitions.canInfuse(2,1,3));assertFalse(RareDefinitions.canInfuse(2,2,3));assertFalse(RareDefinitions.canInfuse(3,1,3));assertFalse(RareDefinitions.canInfuse(0,Integer.MAX_VALUE,3));}
 @Test public void everySuppliedRecipeHasNineCellsAndOneExactEssence(){assertEquals(33,RareDefinitions.ALL.size());Set<List<Material>> recipes=new HashSet<>();for(var d:RareDefinitions.ALL.values()){assertEquals(9,d.ingredients().size());assertEquals(1,d.ingredients().stream().filter(m->m==Material.AIR).count());assertEquals(Material.AIR,d.ingredients().get(4));assertTrue(recipes.add(d.ingredients()));assertTrue(d.maximum()>0&&d.maximum()<=8);assertTrue(d.cost()>=0);assertNotNull(RareDefinitions.get(d.id()));}}
 @Test public void expensiveMaterialsAndSimilarRepairRecipesStayDistinct(){var venom=RareDefinitions.get("poison").ingredients();assertEquals(4,Collections.frequency(venom,Material.SPIDER_EYE));assertEquals(3,Collections.frequency(venom,Material.FERMENTED_SPIDER_EYE));assertEquals(2,Collections.frequency(RareDefinitions.get("calllighting").ingredients(),Material.BEACON));assertEquals(Material.DIAMOND,RareDefinitions.get("durability").ingredients().get(7));assertEquals(Material.SMITHING_TABLE,RareDefinitions.get("repairitem").ingredients().get(7));assertEquals(Material.IRON_CHAIN,RareDefinitions.get("disarm").ingredients().get(1));}
 @Test public void suppliedMaximaCostsAndCooldownsAreRetained(){assertEquals(8,RareDefinitions.get("invisibility").maximum());assertEquals(60,RareDefinitions.get("invisibility").cooldown());assertEquals(8,RareDefinitions.get("invisibility").cost());assertEquals(20,RareDefinitions.get("repairitem").cost());assertEquals(3,RareDefinitions.get("repairitem").cooldown());assertEquals(20,RareDefinitions.get("burst").cooldown());assertEquals(30,RareDefinitions.get("greaterburst").cooldown());for(String id:new String[]{"durability","regeneration","nofalldamage","doublejump","fly","hardy","clarity","hungersteal"})assertEquals(0,RareDefinitions.get(id).cost());}
 @Test public void toolsAndArmorSporeCannotBeConfused(){assertEquals(RareCompatibility.Group.TOOLS,RareCompatibility.property("spore"));assertTrue(RareCompatibility.accepts("spore",Material.NETHERITE_PICKAXE));assertFalse(RareCompatibility.accepts("spore",Material.NETHERITE_CHESTPLATE));assertTrue(RareCompatibility.accepts("aura_esporas",Material.NETHERITE_CHESTPLATE));assertFalse(RareCompatibility.accepts("aura_esporas",Material.NETHERITE_PICKAXE));assertTrue(RareCompatibility.accepts("fertilize",Material.IRON_HOE));assertFalse(RareCompatibility.accepts("fertilize",Material.IRON_PICKAXE));assertTrue(RareCompatibility.accepts("doublejump",Material.DIAMOND_BOOTS));assertFalse(RareCompatibility.accepts("doublejump",Material.DIAMOND_HELMET));}
 @Test public void maximumFallProtectionIsFullWithoutStacking(){assertEquals(1,RareDefinitions.fallMultiplier(0),0);assertEquals(.75,RareDefinitions.fallMultiplier(1),0);assertEquals(0,RareDefinitions.fallMultiplier(4),0);assertEquals(0,RareDefinitions.fallMultiplier(99),0);}
 @Test public void clarityAndExecutionHaveBoundedProgression(){assertEquals(200,RareDefinitions.clarityTicks(200,0));assertEquals(150,RareDefinitions.clarityTicks(200,1));assertEquals(50,RareDefinitions.clarityTicks(200,3));assertEquals(50,RareDefinitions.clarityTicks(200,99));assertEquals(.10,RareDefinitions.executeThreshold(1),.00001);assertEquals(.25,RareDefinitions.executeThreshold(4),.00001);}
 @Test public void repairsUseMaximumDurabilityRatherThanCurrentDamage(){assertEquals(20,RareDefinitions.repairAmount(100,1));assertEquals(100,RareDefinitions.repairAmount(100,5));assertEquals(100,RareDefinitions.repairAmount(100,99));assertEquals(Material.STONE,RareTools.smelt(Material.COBBLESTONE));assertEquals(Material.IRON_INGOT,RareTools.smelt(Material.RAW_IRON));assertNull(RareTools.smelt(Material.DIAMOND));assertEquals(RareTools.treeFamily(Material.OAK_LOG),RareTools.treeFamily(Material.STRIPPED_OAK_WOOD));assertNotEquals(RareTools.treeFamily(Material.OAK_LOG),RareTools.treeFamily(Material.SPRUCE_LOG));}
 @Test public void deniedAndInvalidDamageCannotActivateCombatPowers(){assertFalse(RareCombat.accepted(true,12));assertFalse(RareCombat.accepted(false,0));assertFalse(RareCombat.accepted(false,-1));assertFalse(RareCombat.accepted(false,Double.NaN));assertFalse(RareCombat.accepted(false,Double.POSITIVE_INFINITY));assertTrue(RareCombat.accepted(false,.01));assertTrue(RareCombat.behind(-.9));assertFalse(RareCombat.behind(.9));}
}
